"""Build a self-contained offline textual showcase with local art and fonts."""
from pathlib import Path
import json, html
R=Path(__file__).resolve().parents[1]
slides=json.loads((R/'content/slides_v01.json').read_text())['slides']
E=lambda s:html.escape(str(s))
def items(x):return '<ul>'+''.join('<li>'+E(t)+'</li>' for t in x)+'</ul>'
def content(s):
 out=[]
 if s.get('body'):out.append(items(s['body']))
 cols=s.get('columns',s.get('headers',[]))
 if s.get('rows'):
  out.append('<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+E(c)+'</th>' for c in cols)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+E(c)+'</td>' for c in row)+'</tr>' for row in s['rows'])+'</tbody></table></div>')
 elif cols and isinstance(cols[0],dict):
  out.append('<div class="columns">'+''.join('<div><h3>'+E(c.get('title',c.get('heading','')))+'</h3>'+items(c['body'])+'</div>' for c in cols)+'</div>')
 if s.get('steps'):
  out.append('<ol class="steps">'+''.join('<li><strong>'+E(t['label'])+'</strong><span>'+E(t['detail'])+'</span></li>' for t in s['steps'])+'</ol>')
 if s.get('metrics'):
  out.append('<dl class="metrics">'+''.join('<div><dt>'+E(m['value'])+'</dt><dd>'+E(m['label'])+'</dd></div>' for m in s['metrics'])+'</dl>')
 if s.get('body_extra'):out.append(items(s['body_extra']))
 if s.get('chart'):
  out.append('<p class="note">Recorded synthetic reserve history; not physical field readings.</p><table><thead><tr><th>Scenario seconds</th><th>Reserve displacement (micrometres)</th></tr></thead><tbody>'+''.join('<tr><td>'+E(x['x'])+'</td><td>'+E(x['y'])+'</td></tr>' for x in s['chart']['series'])+'</tbody></table>')
 if s.get('pin'):out.append('<p class="identity"><strong>External expected pin</strong><br>'+E(s['pin'])+'</p>')
 out.append('<details><summary>Technical explanation and source bindings</summary><p>'+E(s['notes'])+'</p><ul class="sources">'+''.join('<li>'+E(x.get('archive',''))+'<br><code>'+E(x.get('member',x.get('path','')))+'<br>'+E(x.get('sha256',''))+'</code></li>' for x in s.get('sources',[]))+'</ul></details>')
 return ''.join(out)
css='''@font-face{font-family:Inter;src:url(assets/fonts/Inter-Regular.ttf)}@font-face{font-family:Inter;font-weight:700;src:url(assets/fonts/Inter-Bold.ttf)}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#fff;color:#1d1d1f;font:17px/1.55 Inter,Arial,sans-serif}a{color:#0067cb;text-underline-offset:5px}header,main,footer{max-width:1120px;margin:auto;padding:0 48px}header{padding-top:38px}nav{display:flex;gap:22px;flex-wrap:wrap;border-bottom:1px solid #dce1e7;padding-bottom:20px;font-size:13px}nav strong{margin-right:auto;letter-spacing:1.2px}.hero{min-height:520px;display:flex;align-items:center;position:relative}.hero img{position:absolute;width:100%;right:0;top:5%;z-index:-1}.hero-text{max-width:55%}.eyebrow{color:#0071e3;font-size:13px;letter-spacing:1.4px;text-transform:uppercase;font-weight:700}h1{font-size:clamp(48px,6vw,76px);line-height:1.03;letter-spacing:-3px;margin:14px 0 24px}h2{font-size:34px;line-height:1.18;letter-spacing:-1px;max-width:880px;margin:12px 0 18px}h3{font-size:19px}.lead{font-size:21px;color:#4b515a;max-width:760px}section{padding:52px 0;border-top:1px solid #dce1e7}.columns{display:grid;grid-template-columns:1fr 1fr;gap:46px}li{margin-bottom:9px}ul{padding-left:23px}.steps{counter-reset:flow;list-style:none;padding:0;margin:30px 0;display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:28px}.steps li{counter-increment:flow;border-top:3px solid #0071e3;padding-top:15px}.steps li:before{content:counter(flow,decimal-leading-zero);font-size:13px;color:#0071e3;display:block;margin-bottom:8px}.steps strong,.steps span{display:block}.steps span{font-size:15px;color:#59616c;margin-top:8px}table{border-collapse:collapse;width:100%;font-size:16px;margin:25px 0}th,td{text-align:left;vertical-align:top;padding:15px 16px 15px 0;border-bottom:1px solid #dce1e7}th{border-bottom:2px solid #1d1d1f}th:first-child,td:first-child{width:25%}.metrics{display:flex;gap:48px;margin:28px 0;flex-wrap:wrap}.metrics dt{font-size:50px;letter-spacing:-2px;color:#0071e3;font-weight:700}.metrics dd{margin:0;font-size:14px;color:#59616c}.identity{font-size:12px;overflow-wrap:anywhere}details{margin-top:26px;font-size:14px;color:#565e69}summary{cursor:pointer;color:#0067cb}.sources{font-size:11px;overflow-wrap:anywhere}.sources code{font-family:Inter,Arial,sans-serif}.table-wrap{overflow-x:auto}footer{padding-top:30px;padding-bottom:42px;font-size:12px;color:#59616c}.note{font-size:12px;color:#59616c}.index{display:flex;gap:12px;flex-wrap:wrap;padding:22px 0;font-size:12px}a:focus-visible,summary:focus-visible{outline:2px solid #0071e3;outline-offset:5px}@media(max-width:700px){header,main,footer{padding-left:22px;padding-right:22px}.hero{min-height:540px;align-items:flex-start;padding-top:35px}.hero-text{max-width:100%}.hero img{top:240px;width:115%;right:-15px}.hero h1{font-size:54px}.hero .lead{font-size:18px;max-width:300px}.columns{grid-template-columns:1fr;gap:10px}h2{font-size:28px}.metrics{gap:25px}table{font-size:14px}.steps{grid-template-columns:1fr 1fr}section{padding:34px 0}.lead{font-size:18px}}@media print{details{display:block}details>summary{display:none}.hero{min-height:330px}section{break-inside:avoid}nav,.index{display:none}body{font-size:11pt}h2{font-size:22pt}}'''
parts=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Landslide Sentinel | Radiolaria OS</title><style>'+css+'</style><header><nav><strong>RADIOLARIA OS</strong><a href="landslide_sentinel_showcase_v01.pdf">Presentation PDF</a><a href="landslide_sentinel_showcase_v01.pptx">Editable PPTX</a><a href="technical_appendix_v01.pdf">Technical appendix</a><a href="LLM_READER_LANDSLIDE_SENTINEL_PRESENTATION_V02_20260921.xml">LLM reader</a></nav></header><main><div class="hero"><img src="assets/radiolaria_landslide_sentinel_hero.png" alt="Conceptual six-spine white and cobalt radiolarian sculpture"><div class="hero-text"><p class="eyebrow">Landslide Sentinel v0.1</p><h1>Local responsibility.<br>Replaceable intelligence.</h1><p class="lead">A cell that keeps monitoring when the network disappears.</p><p class="note">Source 2f328be · 15 September 2026<br>Conceptual artwork; synthetic physical demonstration.</p></div></div><div class="index">']
parts.extend('<a href="#s'+str(s['number'])+'">'+str(s['number']).zfill(2)+'</a>' for s in slides[1:])
parts.append('</div>')
for s in slides[1:]:
 parts.append('<section id="s'+str(s['number'])+'"><p class="eyebrow">'+str(s['number']).zfill(2)+' / '+E(s.get('kicker','Landslide Sentinel'))+'</p><h2>'+E(s['title']).replace('\n','<br>')+'</h2><p class="lead">'+E(s['lead'])+'</p>'+content(s)+'</section>')
parts.append('</main><footer>Radiolaria OS / Landslide Sentinel v0.1. Explanatory publication based on identified source and preserved evidence. The frozen safe-package anchor does not certify this new presentation or full native replay. <a href="PRESENTATION.md">Scope and file index</a>.</footer></html>')
(R/'output/story.html').write_text('\n'.join(parts))
print('Wrote offline story:',len(parts),'sections/fragments')
